ON CONFLICT (field_code) DO UPDATE SET
    domain           = EXCLUDED.domain,
    section          = EXCLUDED.section,
    label_ko         = EXCLUDED.label_ko,
    label_en         = EXCLUDED.label_en,
    data_type        = EXCLUDED.data_type,
    unit             = COALESCE(EXCLUDED.unit, requirement_field.unit),
    is_required      = EXCLUDED.is_required,
    responsible_role = EXCLUDED.responsible_role,
    sort_order       = EXCLUDED.sort_order,
    tier             = EXCLUDED.tier,
    binding_strength = EXCLUDED.binding_strength,
    legal_basis      = EXCLUDED.legal_basis,
    t1_condition     = EXCLUDED.t1_condition,
    disclosure_scope = EXCLUDED.disclosure_scope,
    data_source      = EXCLUDED.data_source,
    spec_ref         = EXCLUDED.spec_ref,
    is_mvp           = EXCLUDED.is_mvp,
    review_note      = EXCLUDED.review_note;
-- is_auto / field_kind / storage_target 는 일부러 덮어쓰지 않는다. 기존 행에서 이 셋은
-- 화면 배치(입력폼 vs 문서슬롯 vs 자재구성)를 결정하는데, 분류표에는 그 구분이 없어서
-- 덮어쓰면 CHEM_COMPOSITION 같은 자재구성 필드가 일반 입력칸으로 튀어나온다.

-- ── 기존 80개 행 sort_order 를 새 밴드로 재배치 ────────────────────────
UPDATE requirement_field rf
   SET sort_order = s.band * 1000 + 500 + (rf.sort_order % 100)
  FROM (VALUES
        ('IDENTIFIER', 1),
        ('OPERATOR', 2),
        ('SPEC', 3),
        ('COMPOSITION', 4),
        ('MATERIAL', 5),
        ('CHEMISTRY', 6),
        ('MECHANICAL', 7),
        ('PERFORMANCE', 8),
        ('PROCESS', 9),
        ('RESOURCE', 10),
        ('CRM', 11),
        ('CARBON', 12),
        ('HAZARD', 13),
        ('CIRCULAR', 14),
        ('PACKAGING', 15),
        ('BMS', 16),
        ('DUE_DILIGENCE', 17),
        ('TRADE', 18),
        ('DOCUMENT', 19),
        ('SYSTEM', 20),
        ('APPROVAL', 21)
       ) AS s(section, band)
 WHERE rf.section = s.section
   AND rf.sort_order < 1000;

-- ── 새 필드의 티어별 노출 규칙 ────────────────────────────────────────
-- disclosure_scope 에서 기계적으로 만든다. 지금까지는 V4/V16/V17 이 필드코드를 손으로
-- 나열해서 심었는데(V13 은 아예 빠뜨렸다), 300개를 손으로 적을 수는 없다.
--   PUBLIC       : 1/2/3 전부 FULL
--   RESTRICTED   : 티어1 HIDDEN, 티어2 MASKED, 티어3 FULL
--   TRADE_SECRET : 티어1·2 HIDDEN, 티어3 MASKED (값 자체는 티어3에도 안 준다)
INSERT INTO field_visibility (field_code, tier_level, visibility)
SELECT rf.field_code, t.lvl,
       CASE rf.disclosure_scope
         WHEN 'PUBLIC'       THEN 'FULL'
         WHEN 'RESTRICTED'   THEN CASE t.lvl WHEN 1 THEN 'HIDDEN' WHEN 2 THEN 'MASKED' ELSE 'FULL' END
         ELSE                     CASE t.lvl WHEN 3 THEN 'MASKED' ELSE 'HIDDEN' END
       END
  FROM requirement_field rf
 CROSS JOIN (VALUES (1),(2),(3)) AS t(lvl)
    ON CONFLICT (field_code, tier_level) DO UPDATE
   SET visibility = EXCLUDED.visibility;

